from collections.abc import Iterable

def smallest_change(arr):
    """Return the minimal number of changes required to make arr a palindrome."""
    if arr is None or not isinstance(arr, Iterable):
        raise TypeError("Input must be an iterable")
    arr_list = list(arr)
    length = len(arr_list)
    if length < 2:
        return 0
    changes = 0
    for i in range(length // 2):
        if arr_list[i] != arr_list[-(i + 1)]:
            changes += 1
    return changes

